import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._queued = {}
        self._next_id = 1
        self._generation = 0

    def add_customer(self, name: str, vip: bool = False) -> None:
        if name in self._customers:
            raise ValueError("Customer already exists")
        self._customers[name] = vip

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        if not title:
            raise ValueError("Title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")
        vip = self._customers[customer]

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = (vip, priority)
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        if ticket_id in self._queued:
            return
        vip, priority = self._tickets[ticket_id]
        self._generation += 1
        self._queued[ticket_id] = self._generation
        heapq.heappush(
            self._queue,
            (
                not vip,
                -self.PRIORITIES.index(priority),
                ticket_id,
                self._generation,
            ),
        )

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id, generation = heapq.heappop(self._queue)
            if self._queued.get(ticket_id) == generation:
                del self._queued[ticket_id]
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(ticket_id)
        self._queued.pop(ticket_id, None)

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(ticket_id)
        self._enqueue(ticket_id)
